{
  "findings": [
    {
      "check_id": "CKV_AWS_356",
      "title": "Ensure no IAM policies documents allow "*" as a statement's resource for restrictable actions",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "HIGH",
      "explanation": "The policy grants `ssm:StartSession` and other SSM session management actions on `Resource = "*"`. This allows the principal to start sessions on any EC2 instance in the account, significantly increasing the blast radius of privilege escalation or unauthorized access."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
           "ssm:DescribeSessions",
            "ssm:GetConnectionStatus",
            "ssm:DescribeInstanceProperties",
            "ssm:TerminateSession",
            "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ssm:*:*:document/AWS-StartPortForwardingSessionToRemoteHost"
      },
    ]
  })
}",
  "fix_summary": "Replaced the wildcard `Resource = "*"` with a specific ARN pattern for SSM session documents to limit the scope of the permission. Note: In a production environment, this should be further restricted to specific instance IDs or tags using condition keys or more granular resource ARNs depending on the exact use case."
}
